function toggleTheme(){
    const t=document.documentElement.getAttribute("data-theme"),e="dark"===t?"light":"dark";
    document.documentElement.setAttribute("data-theme",e),localStorage.setItem("theme",e);
    const sun=document.querySelector(".theme-icon-sun"),moon=document.querySelector(".theme-icon-moon");
    if (e==="light") {
        sun.style.display = "inline-block";
        moon.style.display = "none";
    } else {
        sun.style.display = "none";
        moon.style.display = "inline-block";
    }
}
function setInitialTheme(){
    const t=localStorage.getItem("theme");
    if(t){
        document.documentElement.setAttribute("data-theme",t);
        const sun=document.querySelector(".theme-icon-sun"),moon=document.querySelector(".theme-icon-moon");
        if (t==="light") {
            sun.style.display = "inline-block";
            moon.style.display = "none";
        } else {
            sun.style.display = "none";
            moon.style.display = "inline-block";
        }
    }else{
        document.documentElement.setAttribute("data-theme","dark");
        const sun=document.querySelector(".theme-icon-sun"),moon=document.querySelector(".theme-icon-moon");
        sun.style.display = "none";
        moon.style.display = "inline-block";
        localStorage.setItem("theme","dark")
    }
}
document.addEventListener("DOMContentLoaded",setInitialTheme);